typedef unsigned long long u_long128 __attribute__((mode(TI)));

extern "C" void *memset(void *, int, unsigned int);
extern "C" int scePadPortOpen(int, int, u_long128 *);

class input_device
{
public:
    input_device();
    virtual ~input_device();
    virtual void poll() = 0;

private:
    int device_id;
};

class os_file
{
public:
    os_file();
};

class demo_keyframe;

extern u_long128 *dma_buf[8];

class ps2_joypad_device : public input_device
{
public:
    ps2_joypad_device(int which_port, int which_slot);
    virtual ~ps2_joypad_device();
    virtual void poll();

private:
    int pad_id;
    int term_id;
    int g_error_count;
    int phase;
    int state;
    unsigned char rdata1[32];
    unsigned char rdata2[32];
    unsigned char *curr_rdata;
    unsigned char *prev_rdata;
    char port_id;
    char slot_id;
    char pad_type;
    bool port_opened;
    int disconnected;
    int was_disconnected;
    bool playing_demo;
    bool recording_demo;
    unsigned int keyframe_count;
    unsigned int curr_keyframe;
    demo_keyframe *demo_data;
    unsigned int frames_since_change;
    os_file demo_log;
};

ps2_joypad_device::ps2_joypad_device(int which_port, int which_slot)
{
    port_id = which_port;
    slot_id = which_slot;

    curr_rdata = rdata1;
    prev_rdata = rdata2;
    memset(rdata1, 0, 32);
    rdata1[2] = 0xff;
    rdata1[3] = 0xff;
    memset(rdata2, 0, 32);
    rdata2[2] = 0xff;
    rdata2[3] = 0xff;
    pad_type = -1;

    frames_since_change = 0;
    keyframe_count = 0;
    curr_keyframe = 0;
    demo_data = 0;
    playing_demo = false;
    recording_demo = false;

    int ret = scePadPortOpen(
        port_id,
        slot_id,
        dma_buf[port_id + slot_id]);
    if (ret == 0)
        port_opened = false;
    else
        port_opened = true;

    disconnected = 0;
    was_disconnected = 0;
    pad_id = 0;
    term_id = 0;
    g_error_count = 0;
    phase = 0;
    state = 0;

    poll();
}
